	"Eu sou rápido, cheguei antes do fone acabar": "Ich bin schnell, da war ich, bevor die Musik aus war",
	"Tô na porta, pode descer": "Ich bin an der Tür, komm runter",
	"Tchau, mercado! Volto logo": "Tschüss, Markt! Bin gleich zurück",
	"Vrum, vrum, lá vou eu": "Brumm, brumm, los geht's",
	"Sacola na mão do cliente, missão cumprida": "Tüte in der Hand des Kunden, Mission erfüllt",
