	"Entregue e sem reclamação, aí sim": "Geliefert ohne Beschwerde, so gehört's",
	"Deixou o pedido inteiro, ótimo": "Die ganze Bestellung, super",
	"Relâmpago na área! Cheguei": "Blitz im Viertel! Da bin ich",
