	"Tô indo, não para não": "Ich fahr los, ohne Halt",
	"Vrum! Já saí da frente": "Brumm! Aus dem Weg",
	"Chegou inteiro, 5 estrelas pra gente": "Heil angekommen, 5 Sterne für uns",
	"Tá entregue, bora pro próximo": "Geliefert, weiter zum Nächsten",
