	"Parei na portaria, pode vir": "Ich hab an der Pforte gehalten, komm her",
	"Fui! Deseja boa noite pro freguês": "Ich fahr los! Wünsch dem Kunden eine gute Nacht",
	"Lá vai o baú, segura a onda": "Da fährt die Box, halt dich fest",
