	"Pedido cancelado ou expirado.": "Bestellung storniert oder abgelaufen.",
	"Essa caixa já está vazia.": "Diese Kiste ist schon leer.",
	"Gelado vai na bolsa térmica!": "Tiefkühlware kommt in die Kühltasche!",
	"Esse vai na sacola de papel.": "Das kommt in die Papiertüte.",
	"{0} já está completo: devolva a sobra para a caixa.": "{0} ist schon vollständig: den Rest zurück in die Kiste legen.",
	"Frágil por último! Ovos ficam no topo.": "Zerbrechliches zuletzt! Eier kommen nach oben.",
