	"Não é do pedido: devolva para a caixa.": "Gehört nicht zur Bestellung: zurück in die Kiste.",
	"Sacola rasgou! Abrimos outra.": "Tüte gerissen! Wir öffnen eine neue.",
	"Sem mais sacolas! Tire algo da sacola.": "Keine Tüten mehr! Nimm etwas aus der Tüte.",
	"{0} (vazia)": "{0} (leer)",
	"Frágeis (ovos, pão, frutas) sempre por último na sacola.": "Zerbrechliches (Eier, Brot, Obst) immer zuletzt in die Tüte.",
	"Só papel: uma sacola extra conta como cuidado. Gelado segue na térmica.": "Nur Papier: eine zusätzliche Tüte zählt als Sorgfalt. Tiefkühlware bleibt in der Kühltasche.",
