	"Congelamento Rápido": "Schnellgefrieren",
	"Melhora as geladeiras que você já tem (não é um móvel novo): bebidas, laticínios, frios e queijos rendem +15%.": "Verbessert deine vorhandenen Kühlschränke (kein neues Möbelstück): Getränke, Milchprodukte, Aufschnitt und Käse bringen +15 %.",
	"Melhora os freezers que você já tem (não é um móvel novo): congelados, sorvetes, carnes e peixes rendem +15%.": "Verbessert deine vorhandenen Gefriertruhen (kein neues Möbelstück): Tiefkühlware, Eis, Fleisch und Fisch bringen +15 %.",
	"Sem espaço na loja": "Kein Platz im Laden",
	"Mova ou guarde móveis e decorações no modo construir, ou cresça o mercado.": "Verschiebe oder verstaue Möbel und Deko im Baumodus oder vergrößere den Markt.",
	"Organizar a loja": "Laden einrichten",
	"Monte a fornada": "Das Blech füllen",
	"Arraste as massas para a assadeira até não sobrar nenhum buraco. Toque numa massa para girar.": "Zieh die Teiglinge aufs Blech, bis keine Lücke mehr bleibt. Tippe einen Teigling an, um ihn zu drehen.",
	"Encaixe todas as massas na assadeira, sem buracos. Toque para girar; arraste uma massa já posta para tirá-la.": "Bring alle Teiglinge ohne Lücken aufs Blech. Tippen dreht; zieh einen gelegten Teigling weg, um ihn zurückzunehmen.",
	"A fornada grande do dia: as massas compridas primeiro, os pãezinhos fecham os buracos. Toque para girar.": "Die große Tagesladung: zuerst die langen Teiglinge, die Brötchen füllen die Lücken. Tippen dreht.",
	"Assadeira cheia!": "Blech voll!",
	"Forno a 200 °C. Tire quando as camadas estiverem douradas e estufadas.": "Ofen auf 200 °C. Hol ihn raus, wenn die Schichten goldbraun und aufgegangen sind.",
	"Folhado perfeito!": "Perfekter Blätterteig!",
	"Dica": "Tipp",
	"Movimentos: {0}  ·  ideal: {1}": "Züge: {0}  ·  ideal: {1}",
	"Gire esta massa e encaixe no lugar marcado.": "Dreh diesen Teigling und leg ihn an die markierte Stelle.",
	"Esta massa vai no lugar marcado.": "Dieser Teigling gehört an die markierte Stelle.",
	"Esta massa está atrapalhando: tire e tente outro lugar.": "Dieser Teigling ist im Weg: nimm ihn weg und probier eine andere Stelle.",
	"até {0} clientes por dia": "bis zu {0} Kunden pro Tag",
	"Encha a câmara de maturação": "Fülle die Reifekammer",
	"Arraste os queijos para a câmara: cada prateleira e cada coluna com um queijo de cada tipo.": "Zieh die Käse in die Kammer: jedes Regal und jede Spalte mit einem Käse jeder Sorte.",
	"Quatro queijos agora: nenhum tipo pode se repetir na mesma prateleira nem na mesma coluna.": "Jetzt vier Käse: keine Sorte darf sich im selben Regal oder in derselben Spalte wiederholen.",
	"A câmara cheia da tábua, com poucas pistas: pense em cada fileira e cada coluna.": "Die volle Kammer für die Käseplatte, mit wenigen Hinweisen: denk an jede Reihe und jede Spalte.",
	"Maturação perfeita!": "Perfekte Reifung!",
	"Corte na medida": "Auf Gewicht schneiden",
	"Arraste as facas: cada porção tem que dar 150 g. Onde a carne é mais grossa, a fatia fica mais estreita.": "Zieh die Messer: jede Portion muss 150 g wiegen. Wo das Fleisch dicker ist, wird die Scheibe schmaler.",
	"Bifes de 300 g cada. A peça é irregular: olhe a altura da carne antes de mover as facas.": "Steaks zu je 300 g. Das Stück ist ungleichmäßig: schau dir die Dicke an, bevor du die Messer bewegst.",
	"Seis peças de 250 g para o kit, com pouca folga na balança.": "Sechs Stücke à 250 g für das Set, mit wenig Spielraum auf der Waage.",
	"Tudo no peso!": "Alles im Gewicht!",
	"Pedidos na balança": "Bestellungen auf der Waage",
	"Monte os pedidos: arraste cada peixe para uma bandeja até cada balança fechar o peso pedido. Use todos.": "Stell die Bestellungen zusammen: zieh jeden Fisch auf ein Tablett, bis jede Waage das bestellte Gewicht zeigt. Nutze alle.",
	"Três pedidos, sete peças: todas têm que ir para alguma bandeja e cada uma fecha o peso exato.": "Drei Bestellungen, sieben Stücke: alle kommen auf ein Tablett und jedes trifft sein genaues Gewicht.",
	"O pedido grande do dia: nove peças em três bandejas, cada uma no peso certinho.": "Die große Bestellung des Tages: neun Stücke auf drei Tabletts, jedes genau im Gewicht.",
	"Pedidos fechados!": "Bestellungen fertig!",
	"Separe os sucos": "Sortiere die Säfte",
	"Toque numa jarra e depois em outra para despejar. O suco só cai sobre o mesmo sabor ou numa jarra vazia.": "Tippe einen Krug und dann einen anderen an, um umzugießen. Saft geht nur auf dieselbe Sorte oder in einen leeren Krug.",
	"Quatro sabores misturados: deixe cada jarra com um sabor só.": "Vier gemischte Sorten: jeder Krug mit nur einer Sorte.",
	"Cinco sabores e só duas jarras vazias: planeje antes de despejar.": "Fünf Sorten und nur zwei leere Krüge: plane, bevor du gießt.",
	"Cada suco na sua jarra!": "Jeder Saft in seinem Krug!",
	"Monte a casquinha do pedido": "Bau die bestellte Waffel",
	"Monte a casquinha seguindo o pedido em desenhos: cada pista fica verde quando está certa.": "Bau die Waffel nach der Bilder-Bestellung: jeder Hinweis wird grün, wenn er stimmt.",
	"Quatro bolas: os sabores encostados ficam um em cima do outro; com pontinhos, é em algum lugar acima.": "Vier Kugeln: Sorten, die sich berühren, liegen direkt übereinander; mit Pünktchen irgendwo darüber.",
	"A casquinha gigante: cinco bolas e todas as pistas verdes.": "Die Riesenwaffel: fünf Kugeln und alle Hinweise grün.",
	"Casquinha certinha!": "Waffel genau richtig!",
	"Medida exata": "Genaues Maß",
	"Toque num recipiente e depois em outro para despejar até um esvaziar ou o outro encher. Consiga a medida pedida.": "Tippe ein Gefäß und dann ein anderes an, um umzugießen, bis eins leer oder das andere voll ist. Erreiche die verlangte Menge.",
	"Os recipientes não têm marcas: só dá para medir enchendo e esvaziando. Chegue na medida exata.": "Die Gefäße haben keine Markierungen: Messen geht nur durch Füllen und Leeren. Erreiche die genaue Menge.",
	"A medida mais difícil da adega: pense alguns passos à frente.": "Das schwierigste Maß im Keller: denk ein paar Schritte voraus.",
	"Medida certinha!": "Genau richtig!",
	"Cada porção: {0} g (± {1} g)": "Jede Portion: {0} g (± {1} g)",
